//! The substrate's own decision points, described (plan I1) — catalogue-only entries for propagation,
//! admission, matching, membership and the authority gates. Metadata only (`mycelium_core::rule`).

use mycelium_core::rule::{Guard, Input, Outcome, OutcomeKind::*, Responsibility::*, RuleDescriptor, TracePolicy::*};

const STORE: Input = Input { source: "the LWW store and its HLC", scope: "this node", freshness: "local, atomic" };
const FRAME: Input = Input { source: "an incoming wire frame", scope: "one peer connection", freshness: "as received" };

